document.addEventListener("htmx:beforeRequest",(e)=>{if(typeof Nette=="undefined")return;if(e.target.tagName!=="FORM")return;if(!Nette.validateForm(e.target))e.preventDefault();});(()=>{let htmxLoaded=!1;"input,focusin".split(",").forEach((event)=>{document.addEventListener(event,(e)=>{if(htmxLoaded)return;htmxLoaded=!0;if(typeof htmx!=="undefined")return;let script=document.createElement("script");if(typeof htmxAssetUrl=="undefined"){script.src="/site/modules/RockForms/lib/htmx.min.js"}else script.src=htmxAssetUrl;document.head.appendChild(script)})})})()